// Content and action hooks for common rules that used to sit in the rule core (plan/27 §3, 2026-10-14): each rule a
// machine can see at the moment of the tool call gets its own file `<rule>_<name>.cjs` (plan/27 §2d), generated by
// `zemory hook guard` and called by guard.cjs from `policy.json › rule_hooks`. Every hook judges only what the call
// ADDS (a line already in the file is not new), carries the rule's own text in its block message (read from the repo's
// 02_RULES at run time — plan/27 §4), and lets the action through on any failure of its own (HP article 9).
//
// A hook returns null (let through), a string (block), or { msg, flag, subject } (block unless the one-use flag
// `.allow-<flag>` is granted — guard.cjs consumes it).
//
// The Vietnamese-without-diacritics judgement is the one `.claude/skills/audit/scripts/lang-scan.mjs` was tuned with
// (tier A syllables · tier B function words · English homographs · data stripped before judging); keep the two in step.
//
// Written with String.raw so backslashes are literal — DO NOT use backticks or dollar-brace inside the sources below.

const PRELUDE = String.raw`"use strict";
const fs = require("node:fs");
const path = require("node:path");

const BT = String.fromCharCode(96);
const relOf = (root, abs) => path.relative(root, path.resolve(root, abs)).replace(/\\/g, "/");
const inside = (rel) => rel && !rel.startsWith("..") && !path.isAbsolute(rel);

// What the call ADDS and REMOVES for a file tool; newLines = added lines not already present (multiset, trimmed).
function edit(payload, root) {
  const tool = payload.tool_name || "";
  const ti = payload.tool_input || {};
  const abs = ti.file_path || ti.notebook_path || "";
  if (!abs || !["Write", "Edit", "MultiEdit", "NotebookEdit"].includes(tool)) return null;
  const rel = relOf(root, abs);
  if (!inside(rel)) return null;
  let added = "", removed = "", exists = false;
  try { exists = fs.existsSync(abs); } catch { exists = false; }
  if (tool === "Write") {
    added = String(ti.content || "");
    try { removed = exists ? fs.readFileSync(abs, "utf8") : ""; } catch { removed = ""; }
  } else if (tool === "Edit") {
    added = String(ti.new_string || ""); removed = String(ti.old_string || "");
  } else if (tool === "MultiEdit") {
    for (const e of ti.edits || []) { added += "\n" + (e.new_string || ""); removed += "\n" + (e.old_string || ""); }
  } else {
    added = String(ti.new_source || "");
  }
  const seen = new Map();
  for (const l of removed.split(/\r?\n/)) { const k = l.trim(); if (k) seen.set(k, (seen.get(k) || 0) + 1); }
  const newLines = [];
  for (const l of added.split(/\r?\n/)) {
    const k = l.trim();
    if (!k) continue;
    const n = seen.get(k) || 0;
    if (n > 0) seen.set(k, n - 1); else newLines.push(l);
  }
  return { tool, abs, rel, added, removed, exists, newLines };
}

// The rule's own text: the line carrying its number plus its continuation lines, capped.
function ruleText(root, file, id) {
  try {
    const lines = fs.readFileSync(path.join(root, file), "utf8").split(/\r?\n/);
    const at = lines.findIndex((l) => l.includes(BT + id + BT) || l.startsWith(id + " "));
    if (at < 0) return "";
    const out = [lines[at]];
    for (let i = at + 1; i < lines.length && out.length < 12; i++) {
      const l = lines[i];
      if (!l.trim() || /^(- |#|\x60\x60\x60|\d{2}-\d+ |<!--)/.test(l)) break;
      out.push(l);
    }
    return out.map((l) => (l.length > 400 ? l.slice(0, 400) + "…" : l)).join("\n");
  } catch {
    return "";
  }
}
function blocked(root, policy, id, what) {
  const text = ruleText(root, policy.rules_file || "", id);
  return "BLOCKED (guard layer 1): rule " + id + " - " + what + (text ? "\n\nThe rule (" + policy.rules_file + "):\n" + text : "");
}

// A DOOR reminder for a rule that cannot be forbidden, only recalled at the right moment: the FIRST matching call of a
// session is blocked with the rule; the same call retried passes. Remembered per session in <hooks>/.seen.json (git-ignored,
// last 50 sessions). No session id to remember by => never block (fail-open).
function remindOnce(payload, root, policy, key) {
  const sid = String(payload.session_id || payload.transcript_path || "");
  if (!sid) return false;
  const file = path.join(root, policy.flags_dir || "docs/hooks", ".seen.json");
  let all = {};
  try { all = JSON.parse(fs.readFileSync(file, "utf8")) || {}; } catch { all = {}; }
  const list = Array.isArray(all[sid]) ? all[sid] : [];
  if (list.includes(key)) return false;
  all[sid] = list.concat(key);
  const keys = Object.keys(all);
  for (const k of keys.slice(0, Math.max(0, keys.length - 50))) delete all[k];
  try { fs.writeFileSync(file, JSON.stringify(all)); } catch { return false; }
  return true;
}
const ONCE = "\nThis is a reminder, shown once per session: retry the same call to continue.";

// Paths the language rules do not reach: other people's code, frozen hand-overs, deliberate ASCII samples.
const LANG_EXEMPT = [/(^|\/)external\//, /(^|\/)attic\//, /\/skills\/write-docx\/reference\//];
const CODE_EXT = /\.(ts|tsx|js|jsx|mjs|cjs|py)$/i;
`;

/** Vietnamese written without diacritics — the lang-scan judgement, line by line. Shared by two hooks. */
const VI_JUDGE = String.raw`
const A = new Set(["khong", "duoc", "nguoi", "viec", "tieng", "nhieu", "truong", "thuong", "phuong",
  "huong", "duong", "luong", "tuong", "chuong", "muon", "ket", "thiet", "dien", "diem",
  "kiem", "hien", "chuyen", "quyen", "tuyen", "nguon", "thuoc", "buoc", "cuoc", "nuoc", "truoc",
  "suot", "luot", "doan", "loai", "ngoai", "xuat"]);
const B = new Set(["va", "la", "cua", "cho", "voi", "tren", "trong", "cac", "cai", "nay", "se",
  "da", "dang", "phai", "neu", "thi", "ma", "roi", "moi", "cung", "chi", "tu", "ve", "theo",
  "truoc", "khi", "luc", "ra", "vao", "len", "xuong", "hoac", "nhu", "nen", "de", "bi", "co", "toi",
  "giai", "toan", "hoan", "khoan"]);
const EN = new Set(["do", "so", "can", "ten", "ban", "van", "no", "to", "in", "on", "at", "be",
  "me", "we", "he", "con", "as", "is", "it", "an", "a", "the", "not", "one", "man", "end", "set",
  "get", "run", "row", "cot", "sau", "hay", "den", "nam", "bang", "dong", "loi", "tinh", "tong",
  "thu", "muc", "danh", "sach", "tep", "gio", "ngay", "thang"]);
const DIACRITIC = /[À-ỹ]/;
const words = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1 $2").split(/[^A-Za-z]+/).filter(Boolean).map((w) => w.toLowerCase());
// null = fine · string = the offending syllables. Data (code spans, quotes, e-mails, URLs, snake_case, [sql]) is
// stripped first; a mixed line counts tier A only; a capitalised word is a proper noun.
function viBare(text) {
  if (/[A-Za-z0-9+/]{60,}={0,2}/.test(text)) return null;
  const mixed = DIACRITIC.test(text);
  const prose = text.split(BT).filter((_, i) => i % 2 === 0).join(" ")
    .replace(/[\w.+-]+@[\w.-]+/g, " ")
    .replace(/\b\w+:\/\/\S+/g, " ")
    .replace(/\[[^\]]*\]/g, " ")
    .replace(/\b[A-Za-z]+(?:_[A-Za-z0-9]+)+\b/g, " ")
    .replace(/"[^"]*"/g, " ");
  const toks = words(mixed ? prose.split(/\s+/).filter((w) => !DIACRITIC.test(w)).join(" ") : prose);
  if (toks.length < 3 && !mixed) return null;
  const lower = words(prose.replace(/\b[A-Z][a-z]+/g, " "));
  const a = [...new Set(toks.filter((t) => A.has(t) && !EN.has(t) && lower.includes(t)))];
  const b = [...new Set(toks.filter((t) => B.has(t) && !EN.has(t) && lower.includes(t)))];
  return a.length >= 1 || (!mixed && b.length >= 4) ? [...a, ...b].join(",") : null;
}
`;

function hook(file: string, body: string): { file: string; source: string } {
  return { file, source: `// ${file} - generated by zemory hook guard (plan/27). Settings: policy.json.\n${PRELUDE}${body}\nmodule.exports = { check };\n` };
}

export const RULE_HOOKS = [
  // 02-24 — EOL: a Write that would turn a CRLF file into LF (or back) rewrites every line and buries the real change.
  hook("02-24_eol-keep.cjs", String.raw`
function style(s) {
  const crlf = (s.match(/\r\n/g) || []).length;
  const lf = (s.match(/\n/g) || []).length - crlf;
  if (crlf > 0 && lf === 0) return "CRLF";
  if (lf > 0 && crlf === 0) return "LF";
  return null;
}
function check(payload, root, policy) {
  try {
    const e = edit(payload, root);
    if (!e || e.tool !== "Write" || !e.exists) return null;
    const before = style(e.removed), after = style(e.added);
    if (!before || !after || before === after) return null;
    // A repo that locks EOL in .gitattributes ("* text=auto ...") lets git normalise; the rule is met there.
    try { if (/^\*\s+text=auto\b/m.test(fs.readFileSync(path.join(root, ".gitattributes"), "utf8"))) return null; } catch {}
    return blocked(root, policy, "02-24", "this Write turns " + e.rel + " from " + before + " into " + after +
      " - every line would show as changed. Use Edit (it keeps the file's line endings) or write with " + before + ".");
  } catch { return null; }
}`),

  // 02-30 — identifiers and file names are ASCII English: a NEW file/folder with a non-ASCII name, or a new
  // declaration whose name has diacritics or an unmistakable Vietnamese syllable.
  hook("02-30_ascii-names.cjs", String.raw`
const DECL = /(?:const|let|var|function|class|interface|type|enum|def)\s+([A-Za-z_$À-￿][\w$À-￿]*)/g;
const ID_A = new Set(["khong", "duoc", "nguoi", "viec", "tieng", "nhieu", "truong", "thuong", "phuong", "huong", "duong",
  "luong", "tuong", "chuong", "muon", "ket", "thiet", "dien", "diem", "kiem", "hien", "chuyen", "quyen", "tuyen", "nguon",
  "thuoc", "buoc", "cuoc", "nuoc", "truoc", "suot", "luot", "doan", "loai", "ngoai", "xuat"]);
const parts = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1 $2").split(/[^A-Za-z]+/).filter(Boolean).map((w) => w.toLowerCase());
function strip(src, py) {
  if (py) src = src.replace(/#[^\n]*/g, " ");
  return src.replace(/\/\*[\s\S]*?\*\//g, " ").replace(/(^|[^:])\/\/[^\n]*/g, "$1 ")
    .replace(new RegExp(BT + "(?:\\\\[\\s\\S]|[^" + BT + "\\\\])*" + BT, "g"), " ")
    .replace(/'(?:\\[\s\S]|[^'\\\n])*'/g, " ").replace(/"(?:\\[\s\S]|[^"\\\n])*"/g, " ");
}
const NEW_DIR = /^(mkdir|md|new-item|ni|touch)$/i;
function check(payload, root, policy) {
  try {
    const ti = payload.tool_input || {};
    if (typeof ti.command === "string" && ti.command) {
      for (const seg of ti.command.split(/[\n;&|]+/)) {
        const toks = seg.trim().split(/\s+/);
        if (!toks.length || !NEW_DIR.test(toks[0].replace(/^.*[\\/]/, ""))) continue;
        for (const t of toks.slice(1)) {
          const tok = t.replace(/^["']|["']$/g, "");
          if (!tok || tok.startsWith("-") || !/[^\x20-\x7E]/.test(tok)) continue;
          if (!inside(relOf(root, tok))) continue;
          return blocked(root, policy, "02-30", "creating " + tok + " - a file or folder name in the repo is ASCII English.");
        }
      }
      return null;
    }
    const e = edit(payload, root);
    if (!e || LANG_EXEMPT.some((re) => re.test(e.rel))) return null;
    if (!e.exists) {
      const bad = e.rel.split("/").find((p) => /[^\x20-\x7E]/.test(p));
      if (bad) return blocked(root, policy, "02-30", "creating " + e.rel + " - the name part '" + bad + "' is not ASCII English.");
    }
    if (!CODE_EXT.test(e.rel)) return null;
    const code = strip(e.newLines.join("\n"), /\.py$/i.test(e.rel));
    const hits = [];
    for (const m of code.matchAll(DECL)) {
      const name = m[1];
      if (/[^\x00-\x7F]/.test(name)) hits.push(name + " (non-ASCII)");
      else { const v = parts(name).filter((w) => ID_A.has(w)); if (v.length) hits.push(name + " (" + v.join(",") + ")"); }
    }
    if (!hits.length) return null;
    return blocked(root, policy, "02-30", "new identifier(s) in " + e.rel + " that are not ASCII English: " + hits.slice(0, 5).join(" · ") +
      ". Only comments may be Vietnamese.");
  } catch { return null; }
}`),

  // 02-26 (+ 02-29 commit messages, 02-31 ①) — no Vietnamese without diacritics: new prose in .md files, new comment
  // lines in code, and the message of a git commit.
  hook("02-26_vi-diacritics.cjs", VI_JUDGE + String.raw`
// The comment part of a code line. String literals go first: a "//" inside a string (a URL, a test fixture) is data —
// caught on this very test file the day the hook was built.
function commentText(line, py) {
  const code = line.replace(new RegExp(BT + "(?:\\\\.|[^" + BT + "\\\\])*" + BT, "g"), "''")
    .replace(/'(?:\\.|[^'\\])*'/g, "''").replace(/"(?:\\.|[^"\\])*"/g, "''");
  const m = code.match(py ? /#\s*(.*)$/ : /(?:(?:^|[^:])\/\/|\/\*|^\s*\*)\s*(.*)$/);
  return m ? m[1] : null;
}
function commitMessages(cmd, root) {
  if (!/\bgit\b[^\n]*\bcommit\b/.test(cmd)) return [];
  const out = [];
  for (const m of cmd.matchAll(/(?:^|\s)-m\s*(?:"((?:\\"|[^"])*)"|'([^']*)')/g)) out.push(m[1] || m[2] || "");
  const f = /(?:^|\s)(?:-F|--file)\s+("[^"]+"|'[^']+'|\S+)/.exec(cmd);
  if (f) { try { out.push(fs.readFileSync(path.resolve(root, f[1].replace(/^["']|["']$/g, "")), "utf8")); } catch {} }
  return out;
}
function check(payload, root, policy) {
  try {
    const ti = payload.tool_input || {};
    let lines = [], where = "";
    if (typeof ti.command === "string" && ti.command) {
      for (const msg of commitMessages(ti.command, root)) lines.push(...msg.split(/\r?\n/).filter((l) => !/^Co-Authored-By:/i.test(l)));
      where = "the commit message";
    } else {
      const e = edit(payload, root);
      if (!e || LANG_EXEMPT.some((re) => re.test(e.rel))) return null;
      where = e.rel;
      if (/\.md$/i.test(e.rel)) lines = e.newLines.filter((l) => !/^\s*\x60\x60\x60/.test(l));
      else if (CODE_EXT.test(e.rel)) lines = e.newLines.map((l) => commentText(l, /\.py$/i.test(e.rel))).filter((x) => x !== null);
      else return null;
    }
    const bad = [];
    for (const l of lines) { const w = viBare(l); if (w) bad.push("  " + l.trim().slice(0, 100) + "   [" + w + "]"); }
    if (!bad.length) return null;
    return blocked(root, policy, "02-26", "Vietnamese without diacritics in " + where + ":\n" + bad.slice(0, 4).join("\n") +
      "\nWrite it with diacritics, or in English. Names other people chose belong in quotes or backticks.");
  } catch { return null; }
}`),

  // 02-27 — the harness is written as specification: a NEW line in 01–04 or a SKILL.md may not quote the user or date a
  // decision ("user chốt <date>"). Only new lines: older text is rewritten in its own pass (plan/27 §7 ④).
  hook("02-27_spec-voice.cjs", String.raw`
const HARNESS = /(^|\/)(0[1-4]_[A-Z_]+\.md|SKILL\.md)$/;
const VOICE = [
  /\buser\s+chốt\s+\d{4}-\d{2}-\d{2}/i,
  /\(\s*user\s+chốt\b/i,
  /\buser\b[^\n]{0,30}:\s*\*?["“]/i,
  /\buser\s+(?:nói|bảo|yêu cầu)\s*:?\s*\*?["“]/i,
];
function check(payload, root, policy) {
  try {
    const e = edit(payload, root);
    if (!e || !HARNESS.test(e.rel)) return null;
    const bad = e.newLines.filter((l) => VOICE.some((re) => re.test(l)));
    if (!bad.length) return null;
    return blocked(root, policy, "02-27", "new line(s) in " + e.rel + " quote the user or date a decision:\n" +
      bad.slice(0, 3).map((l) => "  " + l.trim().slice(0, 110)).join("\n") +
      "\nState the rule as condition -> behaviour; the original words, date and incident go to 06_CHANGES.");
  } catch { return null; }
}`),

  // 02-1 — a new storage or index layer must be declared and measured on a second machine: the door is the call that adds
  // a table or opens a database.
  hook("02-1_second-machine.cjs", String.raw`
const LAYER = /\bCREATE\s+(?:VIRTUAL\s+)?TABLE\b|\bnew\s+Database\s*\(|\bsqlite3\.connect\s*\(|\bopenMemory\s*\(/i;
function check(payload, root, policy) {
  try {
    const e = edit(payload, root);
    if (!e || !/\.(ts|tsx|js|mjs|cjs|py|sql)$/i.test(e.rel) || /(^|\/)(test|tests|__tests__)\//.test(e.rel) || /\.test\./.test(e.rel)) return null;
    if (!e.newLines.some((l) => LAYER.test(l))) return null;
    if (!remindOnce(payload, root, policy, "02-1")) return null;
    return blocked(root, policy, "02-1", "this adds a storage or index layer in " + e.rel +
      " - declare how it reaches a second machine and measure that path before calling it done (.claude/skills/sync-path/SKILL.md)." + ONCE);
  } catch { return null; }
}`),

  // 02-2 — a text written for readers follows the style rules: the door is creating a file meant to be handed over.
  hook("02-2_reader-text.cjs", String.raw`
const OUT_DIR = /(^|\/)(reports?|deliverables?|outbox|handover|exports?|03_output)\//i;
const OUT_NAME = /(report|bao-?cao|email|mail|memo|handover|ban-?giao|announcement|thong-?bao)[^/]*\.(md|txt|html|docx)$/i;
function check(payload, root, policy) {
  try {
    const e = edit(payload, root);
    if (!e || e.exists || /^(docs\/(agent|plan)|\.claude)\//.test(e.rel)) return null;
    if (!OUT_DIR.test(e.rel) && !OUT_NAME.test(e.rel)) return null;
    if (!remindOnce(payload, root, policy, "02-2")) return null;
    return blocked(root, policy, "02-2", e.rel + " reads as a text handed to people - write it for the reader, by the style rules in .claude/skills/write-style/SKILL.md." + ONCE);
  } catch { return null; }
}`),

  // 02-13 — a new test must be shown able to go red: the door is creating a test file.
  hook("02-13_test-red.cjs", String.raw`
const TEST = /(^|\/)(test|tests|__tests__)\/|\.test\.[cm]?[jt]sx?$|_test\.(py|go)$|(^|\/)test_[^/]+\.py$/i;
function check(payload, root, policy) {
  try {
    const e = edit(payload, root);
    if (!e || e.exists || !TEST.test(e.rel)) return null;
    if (!remindOnce(payload, root, policy, "02-13")) return null;
    return blocked(root, policy, "02-13", "a new test file " + e.rel + " - once it passes, break the code it guards and confirm it goes red; green alone proves nothing." + ONCE);
  } catch { return null; }
}`),

  // 02-47 — standing in a reference repo is read-only: a zemory command that WRITES, aimed at another folder (cd · Set-Location ·
  // pushd · --root), writes into that repo and its store. Flag: .allow-outside.
  hook("02-47_other-repo.cjs", String.raw`
const WRITES = /\bzemory(?:\.cmd)?\s+(init|sync(?!\s+--check)|reindex|archive|migrate|adopt|setup|hook|memory\s+(?:scan|sync|embed|forget|redact)|gates\s+--write-top|project\s+move)\b/i;
function outsideOf(root, dir) {
  const d = String(dir || "").replace(/^["']|["']$/g, "");
  if (!d || d === "-" || /^[~$%]/.test(d)) return false;
  const rel = relOf(root, d);
  return !inside(rel) && rel !== "";
}
function check(payload, root, policy) {
  try {
    const cmd = (payload.tool_input || {}).command;
    if (typeof cmd !== "string" || !WRITES.test(cmd)) return null;
    let target = null;
    if (payload.cwd && outsideOf(root, payload.cwd)) target = payload.cwd;
    const cd = /(?:^|[;&|]\s*)(?:cd|set-location|sl|pushd)\s+("[^"]+"|'[^']+'|\S+)/i.exec(cmd);
    if (!target && cd && outsideOf(root, cd[1])) target = cd[1];
    const r = /--root[= ]("[^"]+"|'[^']+'|\S+)/i.exec(cmd);
    if (!target && r && outsideOf(root, r[1])) target = r[1];
    if (!target) return null;
    return { flag: "outside", subject: cmd, msg: blocked(root, policy, "02-47", "a zemory command that writes, aimed at " + target +
      " - it writes into that repo and its store. Run it from the repo you work in; take the standard by reading docs_template/.") };
  } catch { return null; }
}`),

  // 02-38 — the ledger's way IN: a new open item in 05_TODO needs the user's yes first (one-use flag .allow-todo).
  // Counted, not diffed: rewording or closing an item is not a new item.
  hook("02-38_todo-door.cjs", String.raw`
const OPEN = /^\s*(?:[-*]|\d+\.|#{2,4})\s+\[[ ~]\]/gm;
function check(payload, root, policy) {
  try {
    const e = edit(payload, root);
    if (!e || e.rel !== (policy.todo_file || "")) return null;
    const after = (e.added.match(OPEN) || []).length, before = (e.removed.match(OPEN) || []).length;
    if (after <= before) return null;
    return { flag: "todo", subject: e.rel + ":" + after, msg: blocked(root, policy, "02-38",
      "this adds " + (after - before) + " open item(s) to " + e.rel + " - an item enters the ledger only after the user says yes in this session. " +
      "Ask ONE question with your proposal; a repairing task the user gave, or a duty an existing rule imposes, is said yes to already.") };
  } catch { return null; }
}`),
];
